-- Palladium Fantasy Dragons and Gods - magic weapons (printed 228-232): 23 gear rows.
-- See apps/character-creator/docs/surveys/dag.md.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local  apps/character-creator/db/add-dag-magic-weapons.sql
--   node scripts/d1-apply.mjs --remote apps/character-creator/db/add-dag-magic-weapons.sql
--
-- READ FROM THE TEXT LAYER (cache p229-p233, page_offset 1), cross-checked
-- against pdftotext -layout of the same pages for every number stored.
--
-- THE SECTIONS: "Magic & Holy Weapons" (Castlerake and Frostfoil, printed
-- 228-230), "Other Magic Weapons of the Palladium World": Dragon Bone Weapons
-- (printed 230-231) and Dragon Slayer Weapons (printed 231-232).
--
-- SHAPE, copied from add-pf-magic-items.sql and add-atlantis-rune-weapons.sql:
-- system 'palladium-fantasy'; a generic grade or an item that is not a weapon
-- is category 'magic' (as gryphon-claws is); a NAMED legendary weapon is
-- 'weapon'; the one suit printing an A.R. and an S.D.C. is 'armor'. Cost is
-- the low end of a printed range and cost_note the range. Items printing no
-- price - the Swords of Legend, the Feathered Dragon's Wings, the generic
-- Dragon Slayer Weapon, the rune armor and axe - store NULL, never a guess.
-- sdc on the generic dragon bone weapon is the OBJECT's 100 S.D.C. the page
-- prints; the spear/javelin keeps it in its description, because a row with
-- dice damage and an sdc reads to regression as damage filed as durability.
--
-- NOT HERE, on purpose:
--   Dragon Helm (the Dragon's Skull, printed 231, 800,000 to 1.5 million
--     gold). The name is already taken by `dragon-helm`, "Dragon helm",
--     citing Palladium Fantasy RPG p.249-267 at 200,000 gold. Not overwritten
--     and not duplicated; left for a decision.
--   Castlerake's six pieces: described inside the Castlerake row, not rows.
--   "Additional Greater & Greatest Rune Weapon Powers" (printed 232): optional
--     GM powers for rune weapons - Null Aura, Speed Doubler, Free Will
--     Consciousness, Shape-Changer - with no price and no item; not gear.
--   The Blood of Styphon's "Black Metal" (printed 228): a material, 80,000+
--     gold a pound, in a god's entry rather than this chapter.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, ar, sdc, description, source_book) VALUES
('castlerake-the-conquerors-sword', 'Castlerake, the Conqueror''s Sword', 'palladium-fantasy', 'weapon', NULL, NULL, 'No price: the book calls pricing it ridiculous - a seller may demand tens of millions of gold (printed 229).', '2D4x10 to mortals and supernatural or magical creatures; double to Earth Elementals and Golems', 0, NULL, NULL, NULL, 'Sword of Legend. An intelligent (I.Q. 17, Anarchist) indestructible golden sword over six feet long, set with four rune-bearing gems. +3 to strike, +3 to parry/block. Great Power: driven into the stone of a fortification (P.S. 20 required) and withdrawn a melee round later, one-third of the structure collapses and the rest loses half its S.D.C. and 5 A.R.; 500 P.P.E. per use. Secondary powers: Force Blast (30 ft/10 m, 1D6x10 to all who fail to dodge; 10 P.P.E.), Destructive Vibration (shatters, or cracks for -50% S.D.C. and -2 A.R., a rigid object of 500 S.D.C. or less in one melee round; not living matter; 25 P.P.E.), Consume Magic/P.P.E. (absorbs P.P.E. from those it stabs and magic cast at it or its wielder; 10 P.P.E. per minute). Holds 542 P.P.E.; recharges 16 P.P.E. per day assembled. Broken into six pieces scattered across the Palladium World, each pointing to another while it holds P.P.E. and usable as P.P.E. storage: the Blade (2D6+2 damage alone, effective against undead and supernatural; 150 P.P.E.), Pommel Gem (100), Centerpiece Gem (75), Left Gem (50), Right Gem (40) and Crosspiece (10). Pieces recharge about 1 P.P.E. per day and join automatically when placed together; the personality returns only when complete.', 'Palladium Fantasy Dragons and Gods p.228-229'),
('frostfoil-the-winter-blade', 'Frostfoil, the Winter Blade', 'palladium-fantasy', 'weapon', NULL, NULL, 'Beyond value (printed 230).', '1D4x10; double to Ice Elementals and supernatural monsters vulnerable to cold', 0, NULL, NULL, NULL, 'Sword of Legend, a dwarven claymore (I.Q. 11, Anarchist) that refuses any elf; bonding takes six months for a dwarf, a year for other races. +2 to strike, +1 to parry/block; +5 to the wielder''s P.B. when showing it off. First Great Power: Freeze Bodies of Water - a square mile to three feet deep per melee round, 25 P.P.E. per round; the longest bridge is 16 miles by half a mile in fresh water (8 rounds, 200 P.P.E.), half that in salt water. Second Great Power: Call Winter Storm - summoned in 2D6 hours anywhere in the Palladium World, lasts as long as P.P.E. holds; 25 P.P.E. per day; dispelled by Calm Storms. Secondary powers: Ice Blade (+1 strike, +2 parry, +6 damage, cannot be bound or pinned; 10 P.P.E., lasts up to fifteen minutes), Frost Blade (a wounded opponent is frozen 2D4 melee rounds, then takes 4D6; 25 P.P.E.), and reviving victims of frostbite and freezing (+30% to save vs coma/death). 222 P.P.E. fully charged; regains 10 P.P.E. per hour, or all of it in an hour near a ley line or nexus.', 'Palladium Fantasy Dragons and Gods p.229-230'),
('dragon-bone-weapon', 'Dragon Bone Weapon', 'palladium-fantasy', 'magic', NULL, 50000, '50,000 to 150,000 gold; the 15% made indestructible cost 50% more.', 'As the weapon type; full damage to dragons, creatures of magic and supernatural beings, including vampires', 0, NULL, NULL, 100, 'A weapon made and enchanted from dragon bone by alchemists or deities; most dragons find them offensive and destroy them, and sometimes their makers. About half the usual weight for the weapon type and as strong as steel (100 S.D.C.); 15% are indestructible. Usually blunt weapons, staves, javelins and spears. Radiates magic. Many (70%) magic wands are also made of dragon bone.', 'Palladium Fantasy Dragons and Gods p.230-231'),
('dragon-bone-spear-or-javelin', 'Dragon Bone Spear or Javelin', 'palladium-fantasy', 'magic', NULL, 50000, '50,000 to 150,000 gold.', '3D6', 0, 'Thrown twice as far as normal', NULL, NULL, 'As strong as steel (100 S.D.C.; kept out of the sdc column, which regression reserves from rows whose damage is dice). Flies twice as far as normal; takes a P.S. of 50 or higher to break in half. Inflicts full damage to dragons, creatures of magic and supernatural beings, as every dragon bone weapon does.', 'Palladium Fantasy Dragons and Gods p.231'),
('dragon-bone-arrow', 'Dragon Bone Arrow', 'palladium-fantasy', 'magic', NULL, 8000, '8,000 to 10,000 gold per shaft.', '3D6', 0, 'Twice as far as normal', NULL, NULL, 'Flies twice as far as normal; takes a P.S. of 24 or higher to break in half. Inflicts full damage to dragons, creatures of magic and supernatural beings. Can also be charged with a spell; see the Dragon Bone Arrow: rows.', 'Palladium Fantasy Dragons and Gods p.231'),
('dragon-bone-arrow-charm', 'Dragon Bone Arrow: Charm', 'palladium-fantasy', 'magic', NULL, 30000, NULL, NULL, 0, NULL, NULL, NULL, 'A dragon bone arrow charged with a magic energy spell, released when it strikes, equal to a 5th level spell. Reusable if retrieved. Price is per arrow.', 'Palladium Fantasy Dragons and Gods p.231'),
('dragon-bone-arrow-demon-slayer', 'Dragon Bone Arrow: Demon Slayer', 'palladium-fantasy', 'magic', NULL, 50000, NULL, '5D6 to demons and deevils, always penetrating natural A.R.; normal damage to all other creatures', 0, NULL, NULL, NULL, 'A dragon bone arrow charged with a magic energy spell, released when it strikes, equal to a 5th level spell. Reusable if retrieved. Price is per arrow.', 'Palladium Fantasy Dragons and Gods p.231'),
('dragon-bone-arrow-dragon-slayer', 'Dragon Bone Arrow: Dragon Slayer', 'palladium-fantasy', 'magic', NULL, 75000, NULL, '1D4x10 to dragons, always penetrating natural A.R.; normal damage to all other creatures', 0, NULL, NULL, NULL, 'A dragon bone arrow charged with a magic energy spell, released when it strikes, equal to a 5th level spell. Reusable if retrieved. Price is per arrow.', 'Palladium Fantasy Dragons and Gods p.231'),
('dragon-bone-arrow-energy-bolt', 'Dragon Bone Arrow: Energy Bolt', 'palladium-fantasy', 'magic', NULL, 25000, NULL, NULL, 0, NULL, NULL, NULL, 'A dragon bone arrow charged with a magic energy spell, released when it strikes, equal to a 5th level spell. Reusable if retrieved. Price is per arrow.', 'Palladium Fantasy Dragons and Gods p.231'),
('dragon-bone-arrow-fire-ball', 'Dragon Bone Arrow: Fire Ball', 'palladium-fantasy', 'magic', NULL, 40000, NULL, NULL, 0, NULL, NULL, NULL, 'A dragon bone arrow charged with a magic energy spell, released when it strikes, equal to a 5th level spell. Reusable if retrieved. Price is per arrow.', 'Palladium Fantasy Dragons and Gods p.231'),
('dragon-bone-arrow-lightning', 'Dragon Bone Arrow: Lightning', 'palladium-fantasy', 'magic', NULL, 50000, NULL, NULL, 0, NULL, NULL, NULL, 'A dragon bone arrow charged with a magic energy spell, released when it strikes, equal to a 5th level spell. Reusable if retrieved. Price is per arrow. Same as call lightning.', 'Palladium Fantasy Dragons and Gods p.231'),
('dragon-bone-arrow-paralysis-lesser', 'Dragon Bone Arrow: Paralysis: Lesser', 'palladium-fantasy', 'magic', NULL, 20000, NULL, NULL, 0, NULL, NULL, NULL, 'A dragon bone arrow charged with a magic energy spell, released when it strikes, equal to a 5th level spell. Reusable if retrieved. Price is per arrow. Affects the limb or body area struck.', 'Palladium Fantasy Dragons and Gods p.231'),
('dragon-bone-arrow-petrification', 'Dragon Bone Arrow: Petrification', 'palladium-fantasy', 'magic', NULL, 350000, '350,000+ gold per arrow; extremely rare.', NULL, 0, NULL, NULL, NULL, 'A dragon bone arrow charged with a magic energy spell, released when it strikes, equal to a 5th level spell. Reusable if retrieved. Price is per arrow. Turns the person struck to stone unless he makes a save vs magic of 15 or higher.', 'Palladium Fantasy Dragons and Gods p.231'),
('dragon-bone-arrow-with-angel-feathers', 'Dragon Bone Arrow with Angel Feathers', 'palladium-fantasy', 'magic', NULL, 350000, '350,000+ gold; extremely rare.', '2D4x10', 0, 'Four times farther than usual', NULL, NULL, 'A dragon bone shaft fletched with two angel feathers. Flies four times farther than usual and always penetrates the natural A.R. of any supernatural being or creature of magic.', 'Palladium Fantasy Dragons and Gods p.231'),
('dragon-eye-medallion', 'Dragon Eye Medallion', 'palladium-fantasy', 'magic', 3, 500000, '500,000+ gold.', NULL, 0, NULL, NULL, NULL, 'A large round gold medallion shaped like an eye, with a real preserved dragon eye beneath the gold. While worn: see the invisible, recognize enchantment 63%, nightvision 600 feet (183 m), and +10% to the locate secret compartment/door skill. Weighs 3 lbs (1.4 kg).', 'Palladium Fantasy Dragons and Gods p.231'),
('dragon-claw-gloves', 'Dragon Claw Gloves', 'palladium-fantasy', 'magic', NULL, 600000, '600,000 to a million gold; extremely rare.', '6D6 per strike', 0, NULL, NULL, NULL, 'Like the more common Gryphon Claw gloves, but made from the claws of a real dragon. Oversized (a single glove weighs about 30 lbs/13 kg), yet feel light and articulated once worn. Indestructible; the wearer is resistant to fire and cold (half damage). Both gloves must be worn to work, and no other hand-held weapon can be used with them.', 'Palladium Fantasy Dragons and Gods p.231'),
('sorcerers-dragon-helm', 'Sorcerer''s Dragon Helm', 'palladium-fantasy', 'magic', NULL, 1000000, '1-3 million gold.', NULL, 0, NULL, NULL, NULL, 'A less common helm made from the skull of a dragon that lets the wearer cast spell magic whether he knows magic or not: either all first and second level spells, or a total of 16 spells selected from levels 1-4 plus tongues. 60 to 80 P.P.E. available; regenerates 4D6 P.P.E. every three hours.', 'Palladium Fantasy Dragons and Gods p.231'),
('mantle-of-dragon-endurance', 'Mantle of Dragon Endurance', 'palladium-fantasy', 'magic', NULL, 1000000, '1-3 million gold.', NULL, 0, NULL, NULL, NULL, 'An enchanted necklace of dragon bones, nails and/or teeth giving the endurance of a dragon: the wearer can perform prolonged, intense activity at peak efficiency for 1D4+1 weeks on an ounce of food, a cup of water or an hour of sleep. Without proper nourishment the character collapses the moment the mantle is removed.', 'Palladium Fantasy Dragons and Gods p.231'),
('feathered-dragons-wings', 'The Feathered Dragon''s Wings', 'palladium-fantasy', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, 'A pair of feathered wings made from the Kukulcan and worn on the arms of humanoids. Two or more flaps lift the wearer, who can then soar like an eagle: flying speed 110 (75 mph/120 km), maximum altitude one mile (1.6 km), +2 to dodge in flight. No price printed.', 'Palladium Fantasy Dragons and Gods p.231'),
('dragon-slayer-weapon', 'Dragon Slayer Weapon', 'palladium-fantasy', 'magic', NULL, NULL, NULL, 'Normal damage for the weapon type to mortal and demonic opponents; 1D6x10 against dragons', 0, NULL, NULL, NULL, 'A holy sword, knife, axe, mace, morning star or pole arm created to destroy evil dragons, often misused by zealots. Indestructible. Has three of these powers: one additional attack per melee round, only when fighting a dragon; magic lightning bolts at dragons only, once per melee, 6D6 damage, 120 feet (36.6 m), and against a dragon in metamorphosis only when the wielder knows it is one; the wielder is impervious to the special powers and attacks of true dragons, including breath, petrification, horror factor and gaze, but not dragon psionics or cast magic; impervious to psionics from dragons; +2 to save vs a dragon''s magic; regenerate 6D6 points of damage inflicted by a dragon, three times per day. No price printed.', 'Palladium Fantasy Dragons and Gods p.231'),
('black-sword-of-styphon', 'Black Sword of Styphon', 'palladium-fantasy', 'weapon', NULL, NULL, 'Priceless ... millions (printed 232).', '1D6x100 per strike, direct to hit points', 0, NULL, NULL, NULL, 'Sword of Legend: a legendary rune Dragon Slayer sword said to have been commissioned by Styphon to slay his rivals and enemies. The user is impervious to dragon breath attacks, can fly (max. 30 mph/48 km) and is +2 to save vs magic cast by any dragon. If it ever existed, it has been lost for over 50,000 years.', 'Palladium Fantasy Dragons and Gods p.232'),
('dragon-slayer-rune-armor', 'Dragon Slayer Rune Armor', 'palladium-fantasy', 'armor', NULL, NULL, NULL, NULL, 0, NULL, 18, 200, 'A legendary suit of gold full plate rune armor (a greatest rune item, I.Q. 20, alignment anarchist to principled) with a matching rune battle axe; six of the original 500 may still exist. It and its wearer are impervious to cold, heat, fire and all dragon breaths. A.R. 18, S.D.C. 200, regenerating 1D4x10 S.D.C. every 30 seconds (two melee rounds). Weightless and silent, so movement and prowling are not impaired. The wearer is +2 to save vs dragon magic. The armor and axe can never be parted; see Dragon Slayer Rune Axe. No price printed.', 'Palladium Fantasy Dragons and Gods p.232'),
('dragon-slayer-rune-axe', 'Dragon Slayer Rune Axe', 'palladium-fantasy', 'weapon', NULL, NULL, NULL, '3D6 to mortal opponents, 6D6 to demons and other supernatural opponents, 1D6x10 to dragons', 0, 'Thrown 500 feet (152 m); returns', NULL, NULL, 'The greater rune battle axe matched to the Dragon Slayer Rune Armor (I.Q. 20, alignment matches the armor); the two can never be parted. Indestructible. Returns immediately after it is thrown and strikes; +2 to strike dragons. Dragons suffer 1D6x10 damage if they try to grab, hold or use it. No price printed.', 'Palladium Fantasy Dragons and Gods p.232');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'the 23 dag magic weapon rows are in' AS assertion, count(*) AS got, 23 AS want
  FROM gear WHERE slug IN ('castlerake-the-conquerors-sword', 'frostfoil-the-winter-blade', 'dragon-bone-weapon', 'dragon-bone-spear-or-javelin', 'dragon-bone-arrow', 'dragon-bone-arrow-charm', 'dragon-bone-arrow-demon-slayer', 'dragon-bone-arrow-dragon-slayer', 'dragon-bone-arrow-energy-bolt', 'dragon-bone-arrow-fire-ball', 'dragon-bone-arrow-lightning', 'dragon-bone-arrow-paralysis-lesser', 'dragon-bone-arrow-petrification', 'dragon-bone-arrow-with-angel-feathers', 'dragon-eye-medallion', 'dragon-claw-gloves', 'sorcerers-dragon-helm', 'mantle-of-dragon-endurance', 'feathered-dragons-wings', 'dragon-slayer-weapon', 'black-sword-of-styphon', 'dragon-slayer-rune-armor', 'dragon-slayer-rune-axe') AND source_book LIKE 'Palladium Fantasy Dragons and Gods p.%';
SELECT 'every one is palladium-fantasy' AS assertion, count(*) AS got, 0 AS want
  FROM gear WHERE slug IN ('castlerake-the-conquerors-sword', 'frostfoil-the-winter-blade', 'dragon-bone-weapon', 'dragon-bone-spear-or-javelin', 'dragon-bone-arrow', 'dragon-bone-arrow-charm', 'dragon-bone-arrow-demon-slayer', 'dragon-bone-arrow-dragon-slayer', 'dragon-bone-arrow-energy-bolt', 'dragon-bone-arrow-fire-ball', 'dragon-bone-arrow-lightning', 'dragon-bone-arrow-paralysis-lesser', 'dragon-bone-arrow-petrification', 'dragon-bone-arrow-with-angel-feathers', 'dragon-eye-medallion', 'dragon-claw-gloves', 'sorcerers-dragon-helm', 'mantle-of-dragon-endurance', 'feathered-dragons-wings', 'dragon-slayer-weapon', 'black-sword-of-styphon', 'dragon-slayer-rune-armor', 'dragon-slayer-rune-axe') AND system <> 'palladium-fantasy';

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('add-dag-magic-weapons.sql');
